// Routing table (N8N-1.5), first match wins. The summary above is kept in this
// execution for every event, routed or not.
const s = $('Event summary').first().json;
const body = $('TheHive event').first().json.body ?? {};
const cfg = $input.first().json;
const details = body.details !== null && typeof body.details === 'object' ? body.details : {};
const op = s.operation;
const type = s.object_type;
const has = (k) => Object.prototype.hasOwnProperty.call(details, k);
let route;
let status;
if (s.actor === cfg.thehive.n8n_user) {
  // TheHive's webhook reports n8n's own writes back to n8n: stop here.
  route = 'loop'; status = `ignored: caused by ${cfg.thehive.n8n_user} (loop prevention)`;
} else if (op === 'delete') {
  // No object and no useful details (ALERT-TO-THEHIVE §6): open question, N8N-1.5.
  route = 'delete'; status = 'ignored: delete (open question, N8N-1.5)';
} else if (type === 'Alert' && op === 'update' && has('caseId')) {
  route = 'alert-promoted'; status = 'alert promoted to a case (C11; N8N-5.3 stub)';
} else if (type === 'Alert' && op === 'update' && has('status')) {
  route = 'alert-status'; status = 'alert status changed (C11)';
} else if (type === 'Case' && op === 'create') {
  route = 'case-created'; status = 'case created (C11; N8N-5.3 stub)';
} else if (type === 'Case' && op === 'update' && (has('status') || has('stage'))) {
  route = 'case-status'; status = 'case status changed, closing included (C11; N8N-5.3 stub)';
} else if ((type === 'Alert' || type === 'Case') && op === 'update' && has('severity')) {
  route = 'severity-changed'; status = 'severity changed (C11)';
} else if (['Task', 'Log', 'Comment'].includes(type)) {
  route = 'analyst-activity'; status = 'stub: analyst activity (task, log, comment)';
} else {
  route = 'other'; status = 'recorded: no handler';
}
// C9 v0 (interim approval until D-N5's approval task): an alert update whose
// tags newly include lib-config response.approval.tag, by anyone but n8n.
// TheHive 5.7.6 (captured 2026-10-22) sends the tags after the change in
// details.tags, plus details.tagChanges [{operation: added | removed, values}]
// when the tags were set as a list (the UI); an addTags call has no
// tagChanges, so then the tag being in details.tags counts and
// pb-ssh-response's re-read and comment markers decide. Handled next to the
// route above (an event can be both), never instead of it.
const tag = cfg.response?.approval?.tag ?? null;
let approval = null;
if (tag && route !== 'loop' && type === 'Alert' && op === 'update' && Array.isArray(details.tags) && details.tags.includes(tag)) {
  const changes = Array.isArray(details.tagChanges) ? details.tagChanges : null;
  const added = changes === null ? null
    : changes.filter((c) => c && c.operation === 'added').flatMap((c) => (Array.isArray(c.values) ? c.values : []));
  if (added === null || added.includes(tag)) approval = { tag, how: added === null ? 'details.tags (no tagChanges)' : 'details.tagChanges' };
}
return [{ json: { ...s, route, status, details_keys: Object.keys(details), approval } }];

// n8n's own writes (alert, observables, comments, tags) come back as C4
// events: each pb-generic run causes several. Ignored here, before
// lib-config, so a burst doesn't double the work (N8N-1.4). The account is
// lib-config thehive.n8n_user; if they ever differ, "Route" still ignores
// these events, only more slowly. The execution is still saved (C4 check).
const s = $input.first().json;
return [{ json: { ...s, route: 'loop', status: `ignored: caused by ${s.actor} (loop prevention, fast path)` } }];

// C11 (N8N-2.9): which asox-metrics fields this event sets, and on which
// documents. Times are the event's own: the audit record's top-level
// _createdAt (ms), never n8n's clock. First-time fields (t_ack, t_case,
// t_closed) are kept by lib-metrics-upsert when the document has them already.
// Alert events: the alert's sourceRef is the Wazuh alert id (D-N1). Case
// created from an alert: details.fromAlert. Other case events: the case's
// alerts are read from TheHive ("Get case alerts").
const s = $input.first().json;
const body = $('TheHive event').first().json.body ?? {};
const details = body.details !== null && typeof body.details === 'object' ? body.details : {};
const obj = body.object !== null && typeof body.object === 'object' ? body.object : {};
const has = (k) => Object.prototype.hasOwnProperty.call(details, k);
const t = typeof body._createdAt === 'number' ? body._createdAt : null;
const fields = {};
const alertTarget = () => [{ alert_id: obj.sourceRef ?? null, source: obj.source ?? null, thehive_alert_id: obj._id ?? body.objectId ?? null }];
let targets = [];
let caseLookup = null;
if (s.route === 'alert-status') {
  const stage = details.stage ?? obj.stage ?? null;
  // Leaves New: acknowledged. Closed (Ignored, or any closing status):
  // resolution = the status, t_closed; t_ack too when it went straight there.
  if (details.status !== 'New' && stage !== 'New') fields.t_ack = t;
  if (stage === 'Closed' || details.status === 'Ignored') { fields.resolution = details.status; fields.t_closed = t; }
  targets = alertTarget();
} else if (s.route === 'alert-promoted') {
  // Promoted, or merged into a case (ALERT-FORMAT §6 R4).
  if (details.caseId) { fields.case_id = details.caseId; fields.t_case = t; fields.t_ack = t; }
  targets = alertTarget();
} else if (s.route === 'case-created') {
  const from = details.fromAlert ?? obj.fromAlert ?? null;
  fields.case_id = obj._id ?? body.objectId ?? details._id;
  fields.t_case = t;
  fields.t_ack = t;
  targets = from ? [{ alert_id: from.sourceRef ?? null, source: from.source ?? null, thehive_alert_id: from._id ?? null }] : [];
} else if (s.route === 'case-status') {
  // TheHive 5.7 has no separate resolution: a closed case has stage Closed and
  // status = the resolution (TruePositive, FalsePositive, Duplicated, ...).
  if (details.stage === 'Closed') { fields.resolution = details.status; fields.t_closed = t; }
}
// An analyst's severity change, on the alert or the case (whatever the route).
if ((s.object_type === 'Alert' || s.object_type === 'Case') && has('severity')) fields.severity = details.severity;
if (s.route === 'severity-changed' && s.object_type === 'Alert') targets = alertTarget();
if (s.object_type === 'Case' && ['case-status', 'severity-changed'].includes(s.route) && Object.keys(fields).length > 0) {
  caseLookup = body.objectId ?? obj._id ?? null;
}
if (t === null) Object.keys(fields).filter((k) => k.startsWith('t_')).forEach((k) => delete fields[k]);
const nothing = Object.keys(fields).length === 0;
return [{ json: {
  ...s, event_time_ms: t, metrics_fields: fields,
  targets: nothing ? [] : targets, case_lookup: nothing ? null : caseLookup,
  nothing_to_write: nothing || (caseLookup === null && targets.length === 0),
  nothing_reason: nothing ? 'nothing to write for this event' : 'no alert for this event',
} }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. A transient
// failure on the last call goes to lib-error with the number of calls.
const r = $input.first().json;
const policy = $('Config (lib-config)').first().json.thehive_http;
const NODE = 'Get case alerts';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];

// One lib-metrics-upsert call per document (mode update: no document is ever
// created from a C4 event). A case's alerts come from "Get case alerts".
const p = $('Metrics plan (C11)').first().json;
const config = $('Config (lib-config)').first().json;
let targets = p.targets;
if (p.case_lookup !== null) {
  const a = $input.first().json; // "Assess: Get case alerts"
  if (a.decision !== 'response' || a.statusCode !== 200 || !Array.isArray(a.body)) {
    const cls = a.decision === 'error' ? (a.retry_exhausted ? 'thehive_unreachable' : 'thehive_error') : `thehive_${a.statusCode}`;
    return [{ json: { no_write: true, line: `metrics: failed (${cls})`, message: a.message ?? null } }];
  }
  targets = a.body.map((al) => ({ alert_id: al.sourceRef ?? null, source: al.source ?? null, thehive_alert_id: al._id ?? null }));
  if (targets.length === 0) return [{ json: { no_write: true, line: 'metrics: skipped (no alert in this case)' } }];
}
if (p.nothing_to_write || targets.length === 0) return [{ json: { no_write: true, line: `metrics: skipped (${p.nothing_reason})` } }];
return targets.map((tg) => ({ json: {
  mode: 'update', alert_id: tg.alert_id, source: tg.source, thehive_alert_id: tg.thehive_alert_id,
  fields: p.metrics_fields, config,
} }));

// What this event did to asox-metrics, kept on the execution: one line per
// document ("<wazuh alert id>: metrics: ok | skipped (<why)> | failed (<class>)").
const p = $('Metrics plan (C11)').first().json;
const items = $input.all().map((i) => i.json);
const { targets, case_lookup, nothing_to_write, nothing_reason, ...summary } = p;
if (items.length === 1 && items[0].no_write === true) {
  return [{ json: { ...summary, metrics: [items[0].line], metrics_message: items[0].message ?? null } }];
}
return [{ json: { ...summary, metrics: items.map((r) => `${r.alert_id ?? '(no id)'}: ${typeof r.line === 'string' ? r.line : 'metrics: failed (unexpected)'}`),
  metrics_results: items.map(({ config, ...r }) => r) } }];

// C9 v0: the approval event for pb-ssh-response, which checks it (actor, tag
// on the alert, proposal, window, nothing sent yet) and runs the response.
const s = $input.first().json;
const body = $('TheHive event').first().json.body ?? {};
return [{ json: {
  config: $('Config (lib-config)').first().json,
  recv_execution_id: $execution.id,
  event: {
    thehive_alert_id: s.object_id, actor: s.actor,
    event_time_ms: typeof body._createdAt === 'number' ? body._createdAt : null,
    request_id: s.request_id ?? null, how: s.approval.how,
  },
} }];

// pb-ssh-response's result, kept on this execution. On Error = continue: a
// failure inside it arrives as {error} (its own execution and recv-n8n-error
// have the details).
const r = $input.first().json;
const s = $('Route').first().json;
return [{ json: { ...s, approval_result: typeof r.outcome === 'string'
  ? { outcome: r.outcome, code: r.code ?? null, reason: r.reason ?? null, comment: r.comment ?? null }
  : { outcome: 'failed (unexpected)', error: r.error ?? null } } }];
